-- Normalize source-backed company positions and special descriptions.
-- Source: recovered company&position_master Google Sheet.
-- Product/blueprint mappings are intentionally NOT normalized here because
-- the sheet's broader product generation conflicts with the existing 20-row
-- company_products_master catalog.

ALTER TABLE public.company_positions_master
  ADD COLUMN role_key text,
  ADD COLUMN req_amount_primary bigint,
  ADD COLUMN req_amount_secondary bigint,
  ADD COLUMN gain_primary bigint,
  ADD COLUMN gain_secondary bigint,
  ADD COLUMN source_jsonb jsonb;

ALTER TABLE public.company_positions_master
  ADD CONSTRAINT company_positions_role_key_nonempty
    CHECK (role_key IS NULL OR btrim(role_key) <> ''),
  ADD CONSTRAINT company_positions_primary_stat_check
    CHECK (req_stat_primary IS NULL OR req_stat_primary IN ('acu','ops','pre','res')),
  ADD CONSTRAINT company_positions_secondary_stat_check
    CHECK (req_stat_secondary IS NULL OR req_stat_secondary IN ('acu','ops','pre','res')),
  ADD CONSTRAINT company_positions_req_primary_positive
    CHECK (req_amount_primary IS NULL OR req_amount_primary > 0),
  ADD CONSTRAINT company_positions_req_secondary_positive
    CHECK (req_amount_secondary IS NULL OR req_amount_secondary > 0),
  ADD CONSTRAINT company_positions_gain_primary_positive
    CHECK (gain_primary IS NULL OR gain_primary > 0),
  ADD CONSTRAINT company_positions_gain_secondary_positive
    CHECK (gain_secondary IS NULL OR gain_secondary > 0),
  ADD CONSTRAINT company_positions_source_object
    CHECK (source_jsonb IS NULL OR jsonb_typeof(source_jsonb) = 'object');

CREATE UNIQUE INDEX company_positions_type_role_unique_idx
  ON public.company_positions_master (type_id, role_key)
  WHERE role_key IS NOT NULL;

