ALTER TABLE public.company_positions_master
  ALTER COLUMN role_key SET NOT NULL,
  ALTER COLUMN req_amount_primary SET NOT NULL,
  ALTER COLUMN req_amount_secondary SET NOT NULL,
  ALTER COLUMN gain_primary SET NOT NULL,
  ALTER COLUMN gain_secondary SET NOT NULL,
  ALTER COLUMN source_jsonb SET NOT NULL;

ALTER TABLE public.company_specials_master
  ALTER COLUMN is_passive DROP NOT NULL,
  ALTER COLUMN is_passive DROP DEFAULT,
  ADD COLUMN source_special_key text,
  ADD COLUMN semantics_status text,
  ADD COLUMN source_jsonb jsonb;

ALTER TABLE public.company_specials_master
  ADD CONSTRAINT company_specials_star_positive
    CHECK (star_requirement IS NULL OR star_requirement > 0),
  ADD CONSTRAINT company_specials_source_key_nonempty
    CHECK (source_special_key IS NULL OR btrim(source_special_key) <> ''),
  ADD CONSTRAINT company_specials_semantics_status_check
    CHECK (semantics_status IS NULL OR semantics_status IN ('source_description_only','reconciled')),
  ADD CONSTRAINT company_specials_source_object
    CHECK (source_jsonb IS NULL OR jsonb_typeof(source_jsonb) = 'object');

CREATE UNIQUE INDEX company_specials_type_source_key_unique_idx
  ON public.company_specials_master (type_id, source_special_key)
  WHERE source_special_key IS NOT NULL;

